// @ts-check
import { defineConfig } from 'astro/config';
import starlight from '@astrojs/starlight';

// Atoo user documentation → docs.atoo.app (Cloudflare Workers).
// See wrangler.jsonc for deploy config and README.md for the workflow.
//
// The pages under src/content/docs/ are GENERATED by tools/port_user_docs.py
// from the user guide in the development repository; edit them there and
// re-run the port (README.md, "Where the pages come from").
export default defineConfig({
  site: 'https://docs.atoo.app',
  outDir: './dist',
  integrations: [
    starlight({
      title: 'Atoo Docs',
      logo: { src: './src/assets/logo.svg' },
      favicon: '/favicon.svg',
      customCss: ['./src/styles/theme.css'],
      description:
        'User guide for Atoo: a complete show on a Behringer WING from your input list and conventions, written, read back and watched.',
      social: [{ icon: 'external', label: 'atoo.app', href: 'https://atoo.app' }],
      // Dark is the primary look (the app's own); a stored choice still wins.
      head: [
        {
          tag: 'script',
          content:
            "try{if(!localStorage.getItem('starlight-theme'))localStorage.setItem('starlight-theme','dark')}catch(e){}",
        },
      ],
      // Sections follow the app's own areas. The sidebar is AUTO-GENERATED per
      // directory; a page's position comes from `sidebar.order` in its
      // frontmatter, which the port sets.
      //
      // Pages with `draft: true` are shown by `npm run dev` (and
      // `npm run build:staging`) but EXCLUDED from `npm run build`.
      sidebar: [
        { label: 'Getting started', items: [{ autogenerate: { directory: 'getting-started' } }] },
        { label: 'Build', items: [{ autogenerate: { directory: 'build' } }] },
        { label: 'Apply', items: [{ autogenerate: { directory: 'apply' } }] },
        { label: 'Watch', items: [{ autogenerate: { directory: 'watch' } }] },
        { label: 'Patch and amend', items: [{ autogenerate: { directory: 'patch' } }] },
        { label: 'Troubleshooting', items: [{ autogenerate: { directory: 'troubleshooting' } }] },
        { label: 'Reference', items: [{ autogenerate: { directory: 'reference' } }] },
      ],
    }),
  ],
});
